def lcm_polys(polys):
    ans = P.one()
    for f in polys:
        ans = lcm(ans, P(f))
    return ans


def matrix_denominator(M):
    return lcm_polys([K(x).denominator() for x in M.list()])


def ansatz_basis(Dcommon, degree):
    Dcommon = P(Dcommon)
    basis = []
    for i in range(_sage_const_3 ):
        for j in range(_sage_const_3 ):
            for k in range(degree+_sage_const_1 ):
                E = zero33(K)
                E[i, j] = K(n**k/Dcommon)
                basis.append(E)
    return basis


def exact_gauge_basis(Dcommon, degree):
    """
    Return the full QQ-vector space of gauges R=N/Dcommon with
    deg N_ij <= degree satisfying sh(R)*CZh = CP*R.
    """
    basis = ansatz_basis(Dcommon, degree)
    residuals = [gauge_residual(E) for E in basis]

    # Bound the numerator degree of every possible residual entry.
    maxdeg = _sage_const_0 
    forbidden = P.one()
    for i in range(_sage_const_3 ):
        for j in range(_sage_const_3 ):
            dij = lcm_polys([R[i, j].denominator()
                              for R in residuals])
            forbidden = lcm(forbidden, dij)
            for R in residuals:
                f = K(R[i, j]*dij)
                assert f.denominator() == _sage_const_1 
                if f != _sage_const_0 :
                    maxdeg = max(maxdeg, P(f.numerator()).degree())

    # More than maxdeg regular points force each residual numerator to zero.
    points = []
    a = _sage_const_0 
    while len(points) < maxdeg + _sage_const_1 :
        if forbidden(a) != _sage_const_0 :
            points.append(a)
        a += _sage_const_1 

    rows = []
    for a in points:
        for i in range(_sage_const_3 ):
            for j in range(_sage_const_3 ):
                rows.append([ev(R[i, j], a) for R in residuals])

    M = matrix(QQ, rows)
    ker = M.right_kernel()

    gauges = []
    for v in ker.basis():
        G = zero33(K)
        for c, E in zip(v, basis):
            G += c*E
        assert all(x == _sage_const_0  for x in gauge_residual(G).list())
        gauges.append(G)
    return gauges


def marked_affine_space(gauges):
    """
    Impose R(0) zb = xq and R(0) (z2+z3) = xp.
    Returns a particular marked gauge and homogeneous marked directions.
    """
    rdim = len(gauges)
    if rdim == _sage_const_0 :
        return None

    cols = []
    for G in gauges:
        G0 = evM(G, _sage_const_0 )
        cols.append(vector(QQ, list(G0*zb) + list(G0*zm)))
    M = matrix(QQ, _sage_const_6 , rdim)
    for j, col in enumerate(cols):
        M.set_column(j, col)

    rhs = vector(QQ, list(xq) + list(xp))
    if M.rank() != M.augment(rhs).rank():
        return None

    cpart = M.solve_right(rhs)
    cker = M.right_kernel().basis()

    Rpart = zero33(K)
    for c, G in zip(cpart, gauges):
        Rpart += c*G

    Rdirs = []
    for v in cker:
        H = zero33(K)
        for c, G in zip(v, gauges):
            H += c*G
        Rdirs.append(H)

    assert all(x == _sage_const_0  for x in gauge_residual(Rpart).list())
    assert evM(Rpart, _sage_const_0 )*zb == xq
    assert evM(Rpart, _sage_const_0 )*zm == xp
    return Rpart, Rdirs


