    print("det(R)/Delta =", det_ratio)

    y2_initial = evM(R, _sage_const_0 )*z2
    y3_initial = evM(R, _sage_const_0 )*z3
    assert y2_initial + y3_initial == xp
    print("X_0(y^(2)) =", y2_initial)
    print("X_0(y^(3)) =", y3_initial)


