    rows = []
    rhs = []

    def idx(i, j, ell):
        return _sage_const_3  + (_sage_const_3 *i+j)*(degree+_sage_const_1 ) + ell

    for k in range(N):
        if Dcommon(k) == _sage_const_0 :
            continue
        for i in range(_sage_const_3 ):
            for j in range(_sage_const_3 ):
                expr = S(QQ(Dcommon(k))*vals[k][i, j])
                row = [QQ(_sage_const_0 )]*n_unknown
                row[_sage_const_0 ] = expr.monomial_coefficient(s2)
                row[_sage_const_1 ] = expr.monomial_coefficient(s1)
                row[_sage_const_2 ] = expr.monomial_coefficient(s0)
                for ell in range(degree+_sage_const_1 ):
                    row[idx(i, j, ell)] = -QQ(k)**ell
                rows.append(row)
                rhs.append(-expr.constant_coefficient())

    M = matrix(QQ, rows)
    b = vector(QQ, rhs)
    if M.rank() != M.augment(b).rank():
        return None

    sol = M.solve_right(b)
    print("free dimension after fitting =", M.right_kernel().dimension())
    s_found = vector(QQ, sol[:_sage_const_3 ])

    Nmat = zero_matrix(P, _sage_const_3 , _sage_const_3 )
    for i in range(_sage_const_3 ):
        for j in range(_sage_const_3 ):
            Nmat[i, j] = sum(sol[idx(i, j, ell)]*n**ell
                              for ell in range(degree+_sage_const_1 ))

    Rfit = matrix(K, _sage_const_3 , _sage_const_3 ,
                  [K(x/Dcommon) for x in Nmat.list()])

    # Definitive checks: finite interpolation alone is not accepted.
    if any(x != _sage_const_0  for x in gauge_residual(Rfit).list()):
        return None
    if evM(Rfit, _sage_const_0 )*zb != xq or evM(Rfit, _sage_const_0 )*zm != xp:
        return None

    print("correct third state s =", s_found)
    verify_candidate(Rfit)
    return Rfit, s_found


